import std.concurrent as conc

pub type AppError = Failed(String)

fn produce(out: conc.SendOnly<Int64>) {
    out.send(7)
    return
}

pub fn main() -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(4)
    let so = ch.toSendOnly()
    produce(so)
    let ro = ch.toReceiveOnly()
    let got = ro.receive()
    let _ = got
    return Ok(())
}

